## 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <limits.h>

typedef long long ll;

#define MAXN 1005

ll X1[MAXN], Y1[MAXN], X2[MAXN], Y2[MAXN];
ll dist[MAXN];
int vis[MAXN];

ll calc_dist(int i, int j) {
    ll dx = 0, dy = 0;
    if (X2[i] < X1[j]) dx = X1[j] - X2[i];
    else if (X2[j] < X1[i]) dx = X1[i] - X2[j];

    if (Y2[i] < Y1[j]) dy = Y1[j] - Y2[i];
    else if (Y2[j] < Y1[i]) dy = Y1[i] - Y2[j];

    return dx + dy;
}

int main(void) {
    int Xi, Yi, Xf, Yf;
    if (scanf("%d %d %d %d", &Xi, &Yi, &Xf, &Yf) != 4) return 0;

    int N;
    scanf("%d", &N);
    int total = N + 2;

    // Nó 0: início
    X1[0] = X2[0] = Xi;
    Y1[0] = Y2[0] = Yi;

    // Nó 1: fim
    X1[1] = X2[1] = Xf;
    Y1[1] = Y2[1] = Yf;

    // Nós 2..N+1: retângulos
    for (int i = 0; i < N; i++) {
        int x1, y1, x2, y2;
        scanf("%d %d %d %d", &x1, &y1, &x2, &y2);
        X1[i+2] = x1;
        Y1[i+2] = y1;
        X2[i+2] = x2;
        Y2[i+2] = y2;
    }

    // Inicialização do Dijkstra
    for (int i = 0; i < total; i++) {
        dist[i] = LLONG_MAX;
        vis[i] = 0;
    }
    dist[0] = 0;

    for (int step = 0; step < total; step++) {
        int u = -1;
        ll best = LLONG_MAX;
        for (int i = 0; i < total; i++) {
            if (!vis[i] && dist[i] < best) {
                best = dist[i];
                u = i;
            }
        }
        if (u == -1) break;
        if (u == 1) break;  // destino alcançado

        vis[u] = 1;

        for (int v = 0; v < total; v++) {
            if (!vis[v]) {
                ll w = calc_dist(u, v);
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                }
            }
        }
    }

    printf("%lld\n", dist[1]);
    return 0;
}
```

